36	constexpr size_t QUERY_INPUT_INDEX = 0;
37	constexpr size_t KEY_INPUT_INDEX = 1;
38	constexpr size_t VALUE_INPUT_INDEX = 2;
39	constexpr size_t SOFTMAXSUM_OUTPUT_INDEX = 1;
40	constexpr size_t ATTENTIONOUT_OUTPUT_INDEX = 3;
41	constexpr size_t INPUTLAYOUT_ATTRS_INDEX = 5;
42	constexpr size_t MIN_COPY_UINT_SIZE = 32;
43	constexpr size_t VALUE_100 = 100;
44	constexpr size_t VALUE_1024 = 1024;
45	constexpr uint32_t TILING_KEY_1 = 1U;
46	constexpr uint32_t FA_EMPTY_TILING_KEY = 1;
