48	struct EmptyArgs
49	{
50	    uint32_t coreNum;
51	    uint32_t attentionOutFormerNum;          // attentionOut的主核
52	    uint32_t attentionOutTailNum;            // attentionOut的尾核
53	    uint32_t softmaxMaxFormerNum;            // softmaxMax 和 softmaxSum的主核
54	    uint32_t softmaxMaxTailNum;              // softmaxMax 和 softmaxSum的尾核
55	    uint64_t attentionOutSingleCoreDataSize; // attentionOut的每个主核处理的数据个数
56	    uint64_t attentionOutTailCoreDataSize;   // attentionOut的每个尾核处理的数据个数
57	    uint64_t softmaxMaxSingleCoreDataSize;
58	    uint64_t softmaxMaxTailCoreDataSize;
59	    uint64_t attentionOutLastCoreDataSize = 0ULL; // 最后一个核应该处理的数据量
60	    uint64_t attentionOutLastCoreIndex = 0ULL;    // 最后一个核起始地址
61	    uint64_t attentionOutBlockSize = 0ULL;
62	    uint64_t softmaxSumBlockSize = 0ULL;
63	    uint32_t aivActualNum = 0U;
64	    uint64_t tilingKey = 0ULL;
65	};
