75	static ge::graphStatus CheckParams(const gert::TilingContext *context)
76	{
77	    if (context->GetAttrs() != nullptr && context->GetInputShape(QUERY_INPUT_INDEX) != nullptr &&
78	        context->GetInputShape(KEY_INPUT_INDEX) != nullptr && context->GetInputShape(VALUE_INPUT_INDEX) != nullptr) {
79	        auto &valueShape = context->GetInputShape(VALUE_INPUT_INDEX)->GetStorageShape();
80	        auto &keyShape = context->GetInputShape(KEY_INPUT_INDEX)->GetStorageShape();
81	        auto &queryShape = context->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
82	        const char *inputLayout = context->GetAttrs()->GetAttrPointer<char>(INPUTLAYOUT_ATTRS_INDEX);
83	        if (strlen(inputLayout) == 3) { // 3: BSH or SBH
84	            if (inputLayout[0] == 'B') {
85	                // layout is BSH
86	                if (queryShape.GetDim(0) != keyShape.GetDim(0)) {
87	                    std::string shapeMsg = Ops::Base::ToString(queryShape) + " and " +
88	                        Ops::Base::ToString(keyShape);
89	                    OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(context->GetNodeName(), "query and key", shapeMsg.c_str(),
90	                        "The B dim of input query must be the same as the B dim "
91	                        "of input key when the attr input_layout is BSH");
92	                    return ge::GRAPH_FAILED;
93	                }
94	            } else {
95	                if (inputLayout[0] == 'T') { // TND  N1 != N2
96	                    // q_D != k_D
97	                    if (queryShape.GetDim(2) != keyShape.GetDim(2)) {
98	                        std::string shapeMsg = Ops::Base::ToString(queryShape) + " and " +
99	                            Ops::Base::ToString(keyShape);
100	                        OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(context->GetNodeName(),
101	                            "query and key", shapeMsg.c_str(),
102	                            "The D dim of input query must be the same as the D dim of "
103	                            "input key when the attr input_layout is TND");
104	                        return ge::GRAPH_FAILED;
105	                    }
106	                    return ge::SUCCESS;
107	                }
108	                // layout is SBH
109	                if (queryShape.GetDim(1) != keyShape.GetDim(1)) {
110	                    std::string shapeMsg = Ops::Base::ToString(queryShape) + " and " +
111	                        Ops::Base::ToString(keyShape);
112	                    OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(context->GetNodeName(),
113	                        "query and key", shapeMsg.c_str(),
114	                        "The B dim of input query must be the same as the B dim of "
115	                        "input key when the attr input_layout is SBH");
116	                    return ge::GRAPH_FAILED;
117	                }
118	            }
119	            // kD < vD
120	            if (keyShape.GetDim(2) < valueShape.GetDim(2)) {
121	                std::string dMsg = std::to_string(keyShape.GetDim(2)) + " and " +
122	                    std::to_string(valueShape.GetDim(2));
123	                OP_LOGE_FOR_INVALID_VALUES_WITH_REASON(context->GetNodeName(), "key and value",
124	                    dMsg.c_str(), "The value of D dim of input key must be greater than or "
125	                    "equal to the value of D dim of input value");
126	                return ge::GRAPH_FAILED;
127	            }
128	        } else if (strlen(inputLayout) == 4) { // 4: layout is BNSD or BSND
129	            if (queryShape.GetDim(0) != keyShape.GetDim(0)) {
130	                std::string shapeMsg = Ops::Base::ToString(queryShape) + " and " +
131	                    Ops::Base::ToString(keyShape);
132	                OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(context->GetNodeName(), "query and key",
133	                    shapeMsg.c_str(), "The B dim of input query must be the same as the B dim of input key");
134	                return ge::GRAPH_FAILED;
135	            }
136	            if (queryShape.GetDim(3) != keyShape.GetDim(3)) {
137	                std::string shapeMsg = Ops::Base::ToString(queryShape) + " and " +
138	                    Ops::Base::ToString(keyShape);
139	                OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(context->GetNodeName(), "query and key",
140	                    shapeMsg.c_str(), "The D dim of input query must be the same as the D dim of input key");
141	                return ge::GRAPH_FAILED;
142	            }
143	            if (keyShape.GetDim(3) < valueShape.GetDim(3)) {
144	                std::string dMsg = std::to_string(keyShape.GetDim(3)) + " and " + std::to_string(valueShape.GetDim(3));
145	                OP_LOGE_FOR_INVALID_VALUES_WITH_REASON(context->GetNodeName(), "key and value",
146	                    dMsg.c_str(), "The D dim of input key must be greater than or equal to the D dim of input value");
147	                return ge::GRAPH_FAILED;
148	            }
149	        } else {
150	            OP_LOGW(context, "invalid input_layout[%s].", inputLayout);
151	            return ge::GRAPH_FAILED;
152	        }
153	        return ge::SUCCESS;
154	    }
155	    OP_LOGW(context, "fail to get shape or attr from context");
156	    return ge::GRAPH_FAILED;
157	}
