159	static bool GetEmptyArgs(EmptyArgs &emptyArgs, gert::TilingContext *context, const uint32_t &coreNum,
160	                  const uint64_t &attentionOutShapeSize, const int64_t &softmaxSumShapeSize)
161	{
162	    emptyArgs.coreNum = coreNum;
163	    OP_CHECK_IF((coreNum <= 0),
164	                 OP_LOGE(context, "platform info is invalid, coreNum=%u.", coreNum), return false);
165	    auto kernelType = context->GetInputDesc(KEY_INPUT_INDEX)->GetDataType();
166	    OP_CHECK_IF((kernelType != ge::DT_FLOAT16 && kernelType != ge::DT_FLOAT && kernelType != ge::DT_BF16),
167	                OP_LOGE(context, "kernelType is invalid, kernelType is %d.", kernelType),
168	                return false);
169	    uint32_t kernelTypeSize = ge::GetSizeByDataType(kernelType);
170	    OP_CHECK_IF((kernelTypeSize <= 0),
171	               OP_LOGE(context, "kernelType size is invalid, kernelType size is %u.",
172	               kernelTypeSize), return false);
173	    // 计算 MIN_COPY_UINT_SIZE 块数
174	    emptyArgs.attentionOutBlockSize = Ceil(static_cast<uint32_t>(attentionOutShapeSize) * kernelTypeSize,
175	                                           MIN_COPY_UINT_SIZE);
176	    if (attentionOutShapeSize != 0ULL) {
177	        if (static_cast<uint64_t>(emptyArgs.attentionOutBlockSize % coreNum) == 0ULL) {
178	            emptyArgs.attentionOutTailCoreDataSize = 0ULL;
179	            emptyArgs.attentionOutFormerNum = coreNum;
180	            emptyArgs.attentionOutTailNum = 0U;
181	            emptyArgs.attentionOutSingleCoreDataSize = emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE /
182	                                                       kernelTypeSize;
183	            emptyArgs.attentionOutLastCoreDataSize = emptyArgs.attentionOutSingleCoreDataSize -
184	                (emptyArgs.attentionOutBlockSize * MIN_COPY_UINT_SIZE / kernelTypeSize - attentionOutShapeSize);
185	            emptyArgs.attentionOutLastCoreIndex = static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) *
186	                                                  emptyArgs.attentionOutSingleCoreDataSize;
187	        } else {
188	            emptyArgs.attentionOutTailCoreDataSize = emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE /
189	                                                     kernelTypeSize;
190	            emptyArgs.attentionOutSingleCoreDataSize = emptyArgs.attentionOutTailCoreDataSize + MIN_COPY_UINT_SIZE /
191	                                                       kernelTypeSize;
192	            if (emptyArgs.attentionOutBlockSize > coreNum) {
193	                emptyArgs.attentionOutFormerNum = static_cast<uint32_t>(emptyArgs.attentionOutBlockSize % coreNum);
194	                emptyArgs.attentionOutTailNum = coreNum - emptyArgs.attentionOutFormerNum;
195	                emptyArgs.attentionOutLastCoreIndex = 
196	                    static_cast<uint64_t>(emptyArgs.attentionOutFormerNum) * emptyArgs.attentionOutSingleCoreDataSize +
197	                    static_cast<uint64_t>(emptyArgs.attentionOutTailNum - 1U) * emptyArgs.attentionOutTailCoreDataSize;
198	                emptyArgs.attentionOutLastCoreDataSize =
199	                    emptyArgs.attentionOutTailCoreDataSize - (emptyArgs.attentionOutSingleCoreDataSize *
200	                    emptyArgs.attentionOutFormerNum + emptyArgs.attentionOutTailCoreDataSize *
201	                    emptyArgs.attentionOutTailNum - attentionOutShapeSize);
202	            } else {
203	                emptyArgs.attentionOutFormerNum = emptyArgs.attentionOutBlockSize;
204	                emptyArgs.attentionOutTailNum = 0U;
205	                emptyArgs.attentionOutLastCoreIndex = static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) *
206	                    emptyArgs.attentionOutSingleCoreDataSize;
207	                emptyArgs.attentionOutLastCoreDataSize = emptyArgs.attentionOutSingleCoreDataSize -
208	                    (emptyArgs.attentionOutFormerNum * emptyArgs.attentionOutSingleCoreDataSize - attentionOutShapeSize);
209	            }
210	        }
211	    } else {
212	        emptyArgs.attentionOutFormerNum = 0U;
213	        emptyArgs.attentionOutTailNum = 0U;
214	        emptyArgs.attentionOutSingleCoreDataSize = 0ULL;
215	        emptyArgs.attentionOutTailCoreDataSize = 0ULL;
216	        emptyArgs.attentionOutLastCoreDataSize = 0ULL;
217	        emptyArgs.attentionOutLastCoreIndex = 0ULL;
218	    }
219	
220	    uint32_t floatDataSize =  ge::GetSizeByDataType(ge::DT_FLOAT);
221	    OP_CHECK_IF((floatDataSize <= 0),
222	               OP_LOGE(context, "float data size is invalid, size is %u.", floatDataSize),
223	               return false);
224	    // softmaxSum 和 softmaxMax 输出为 fp32
225	    emptyArgs.softmaxSumBlockSize = Ceil(static_cast<uint32_t>(softmaxSumShapeSize) * floatDataSize, MIN_COPY_UINT_SIZE);
226	    if (static_cast<uint64_t>(emptyArgs.softmaxSumBlockSize % coreNum) == 0ULL) {
227	        emptyArgs.softmaxMaxSingleCoreDataSize = emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE /
228	                                                 floatDataSize;
229	        emptyArgs.softmaxMaxTailCoreDataSize = 0U;
230	        emptyArgs.softmaxMaxFormerNum = coreNum;
231	        emptyArgs.softmaxMaxTailNum = 0U;
232	    } else {
233	        if (emptyArgs.softmaxSumBlockSize > coreNum) {
234	            emptyArgs.softmaxMaxFormerNum = static_cast<uint32_t>(emptyArgs.softmaxSumBlockSize % coreNum);
235	            emptyArgs.softmaxMaxTailNum = coreNum - emptyArgs.softmaxMaxFormerNum;
236	        } else {
237	            emptyArgs.softmaxMaxFormerNum = emptyArgs.softmaxSumBlockSize;
238	            emptyArgs.softmaxMaxTailNum = 0U;
239	        }
240	        emptyArgs.softmaxMaxTailCoreDataSize =
241	            emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE / floatDataSize;
242	        emptyArgs.softmaxMaxSingleCoreDataSize =
243	            emptyArgs.softmaxMaxTailCoreDataSize + MIN_COPY_UINT_SIZE / floatDataSize;
244	    }
245	    emptyArgs.aivActualNum = std::max((emptyArgs.attentionOutFormerNum + emptyArgs.attentionOutTailNum),
246	                                      (emptyArgs.softmaxMaxFormerNum + emptyArgs.softmaxMaxTailNum));
247	    return true;
248	}
