316	static bool IsEmptyInput(gert::TilingContext *context)
317	{
318	    auto attentionOutShape = context->GetOutputShape(ATTENTIONOUT_OUTPUT_INDEX);
319	    OP_CHECK_NULL_WITH_CONTEXT(context, attentionOutShape);
320	
321	    auto queryShape = context->GetInputShape(QUERY_INPUT_INDEX);
322	    OP_CHECK_NULL_WITH_CONTEXT(context, queryShape);
323	
324	    auto keyShape = context->GetInputShape(KEY_INPUT_INDEX);
325	    OP_CHECK_NULL_WITH_CONTEXT(context, keyShape);
326	
327	    auto softmaxSumShape = context->GetOutputShape(SOFTMAXSUM_OUTPUT_INDEX);
328	    OP_CHECK_NULL_WITH_CONTEXT(context, softmaxSumShape);
329	
330	    int64_t attentionOutShapeSize = attentionOutShape->GetStorageShape().GetShapeSize();
331	    int64_t queryShapeSize = queryShape->GetStorageShape().GetShapeSize();
332	    int64_t keyShapeSize = keyShape->GetStorageShape().GetShapeSize();
333	    int64_t softmaxSumShapeSize = softmaxSumShape->GetStorageShape().GetShapeSize();
334	    if ((queryShapeSize == 0 || keyShapeSize == 0) && (attentionOutShapeSize != 0 || softmaxSumShapeSize != 0)) {
335	        /* 以 MIN_COPY_UINT_SIZE 为 32Byte说明, blocks为数据的块数, blocks与coreNum存在三种关系:
336	          (1) blocks % coreNum == 0
337	             主核数量为coreNum,主核处理块数为blocks / coreNum, 最后一个核处理非32Byte对齐的数据, 尾核数量为0
338	          (2) blocks % coreNum != 0
339	              (2.1) blocks < coreNum
340	                    主核数量为blocks,主核处理块数为1, 最后一个核处理非32Byte对齐的数据, 尾核数量为0
341	              (2.2) blocks > coreNum
342	                    主核数量为blocks % coreNum, 尾核数量为coreNum - (blocks % coreNum), 尾核处理块数为blocks / coreNum
343	                    主核处理块数为blocks / coreNum + 1,最后一个尾核处理非对齐场景
344	        (2.2)情况如下:
345	        |-------------主核块-----------------|------------尾核块-----------|非对齐块|
346	        |                                   |                             |       |
347	        |                                   |                             |       |
348	        |--------n*(blocks/coreNum+1)-------|-----m*(blocks/coreNum)------|<32Byte|
349	        */
350	        FlashAttentionScoreTilingData* emptyInputTiling = context->GetTilingData<FlashAttentionScoreTilingData>();
351	        emptyInputTiling->reset();
352	        auto compileInfoPtr = reinterpret_cast<const FlashAttentionScoreCompileInfo *>(context->GetCompileInfo());
353	        OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null"),
354	                   return false);
355	        EmptyArgs emptyArgs;
356	        if (!GetEmptyArgs(emptyArgs, context, compileInfoPtr->aivNum, attentionOutShapeSize, softmaxSumShapeSize)){
357	            return false;
358	        }
359	        emptyInputTiling->emptyInputTilingData.set_coreNum(emptyArgs.coreNum);
360	        emptyInputTiling->emptyInputTilingData.set_attentionOutFormerNum(emptyArgs.attentionOutFormerNum);
361	        emptyInputTiling->emptyInputTilingData.set_attentionOutTailNum(emptyArgs.attentionOutTailNum);
362	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxFormerNum(emptyArgs.softmaxMaxFormerNum);
363	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxTailNum(emptyArgs.softmaxMaxTailNum);
364	        emptyInputTiling->emptyInputTilingData.set_attentionOutSingleCoreDataSize(emptyArgs.attentionOutSingleCoreDataSize);
365	        emptyInputTiling->emptyInputTilingData.set_attentionOutTailCoreDataSize(emptyArgs.attentionOutTailCoreDataSize);
366	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxSingleCoreDataSize(emptyArgs.softmaxMaxSingleCoreDataSize);
367	        emptyInputTiling->emptyInputTilingData.set_softmaxMaxTailCoreDataSize(emptyArgs.softmaxMaxTailCoreDataSize);
368	        emptyInputTiling->emptyInputTilingData.set_attentionOutLastCoreDataSize(emptyArgs.attentionOutLastCoreDataSize);
369	        emptyInputTiling->emptyInputTilingData.set_attentionOutLastCoreIndex(emptyArgs.attentionOutLastCoreIndex);
370	        context->SetTilingKey(FA_EMPTY_TILING_KEY);
371	        auto platformInfoPtr = context->GetPlatformInfo();
372	        OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return false);
373	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
374	        context->SetBlockDim(ascendcPlatform.CalcTschBlockDim(emptyArgs.aivActualNum, 0, compileInfoPtr->aivNum));
375	        size_t *workspaces = context->GetWorkspaceSizes(1);
376	        // workspace上预留100M
377	        workspaces[0] = VALUE_100 * VALUE_1024 * VALUE_1024;
378	        return true;
379	    }
380	    return false;
381	}
