383	ASCENDC_EXTERN_C ge::graphStatus TilingFlashAttentionScore(gert::TilingContext *context)
384	{
385	    OP_LOGW(context, "Start registering tiling.");
386	    if (CheckParams(context) != ge::GRAPH_SUCCESS) {
387	        return ge::GRAPH_FAILED;
388	    }
389	 
390	    auto platformInfoPtr = context->GetPlatformInfo();
391	    OP_CHECK_IF(platformInfoPtr == nullptr,
392	        OP_LOGE(context, "platformInfoPtr is null"),
393	        return ge::GRAPH_FAILED);
394	 
395	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
396	    if (ascendcPlatform.GetCurNpuArch() == NpuArch::DAV_3510) {
397	        OP_LOGW(context, "Current npu arch is dav-3510.");
398	        if (IsEmptyInputRegbase(context)) {
399	            return ge::GRAPH_SUCCESS;
400	        }
401	    } else {
402	        OP_LOGW(context, "Current npu arch is not dav-3510.");
403	        if (IsEmptyInput(context)) {
404	            return ge::GRAPH_SUCCESS;
405	        }
406	    }
407	
408	    auto resultCode = TilingRegistryArch::GetInstance().DoTilingImpl(context);
409	    return resultCode;
410	}
