412	ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForFlashAttentionScore(gert::TilingParseContext *context)
413	{
414	    auto platformInfoPtr = context->GetPlatformInfo();
415	    OP_CHECK_IF(platformInfoPtr == nullptr,
416	        OP_LOGE(context, "platformInfoPtr is null"),
