25	
26	namespace Ops {
27	namespace Transformer {
28	namespace OpTiling {
29	
30	template <typename T>
31	std::unique_ptr<TilingBaseClass> TILING_CLASS(gert::TilingContext *context)
32	{
33	    return std::unique_ptr<T>(new (std::nothrow) T(context));
34	}
35	
36	using TilingClassCase = std::unique_ptr<TilingBaseClass> (*)(gert::TilingContext *);
37	
38	class TilingCases {
39	public:
40	    explicit TilingCases(std::string op_type) : op_type_(std::move(op_type))
41	    {
42	    }
43	
44	    template <typename T>
45	    void AddTiling(int32_t priority)
46	    {
47	        OP_CHECK_IF(cases_.find(priority) != cases_.end(), OP_LOGE(op_type_, "There are duplicate registrations."),
48	                    return);
49	        cases_[priority] = TILING_CLASS<T>;
50	        OP_CHECK_IF(cases_[priority] == nullptr,
51	                    OP_LOGE(op_type_, "Register op tiling func failed, please check the class name."), return);
52	    }
53	
54	    const std::map<int32_t, TilingClassCase> &GetTilingCases()
55	    {
56	        return cases_;
57	    }
58	
59	private:
60	    std::map<int32_t, TilingClassCase> cases_;
61	    const std::string op_type_;
62	};
63	
64	// --------------------------------Interfacce with npu arch --------------------------------
65	class TilingRegistryArch {
66	public:
67	    TilingRegistryArch() = default;
68	
69	#ifdef ASCENDC_OP_TEST
70	    static TilingRegistryArch &GetInstance();
71	#else
72	    static TilingRegistryArch &GetInstance()
73	    {
74	        static TilingRegistryArch registry_impl_;
75	        return registry_impl_;
76	    }
77	#endif
78	
79	    std::shared_ptr<TilingCases> RegisterOp(const std::string &op_type, int32_t arch)
80	    {
81	        auto soc_iter = registry_map_.find(arch);
82	        if (soc_iter == registry_map_.end()) {
83	            std::map<std::string, std::shared_ptr<TilingCases>> op_type_map;
84	            op_type_map[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
85	            registry_map_[arch] = op_type_map;
86	        } else {
87	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
88	                soc_iter->second[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
89	            }
90	        }
91	
92	        OP_CHECK_IF(registry_map_[arch][op_type] == nullptr,
93	                    OP_LOGE(op_type, "Register tiling func failed, please check the class name."), return nullptr);
94	        return registry_map_[arch][op_type];
95	    }
96	
97	    ge::graphStatus DoTilingImpl(gert::TilingContext *context)
98	    {
99	        int32_t arch = (int32_t)NpuArch::DAV_RESV;
100	        const char *op_type = context->GetNodeType();
101	        fe::PlatFormInfos *platformInfoPtr = context->GetPlatformInfo();
102	        if (platformInfoPtr == nullptr) {
103	            OP_LOGE(op_type, "Do op tiling failed, cannot get platformInfo.");
104	            return ge::GRAPH_FAILED;
105	        } else {
106	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
107	            arch = static_cast<int32_t>(ascendcPlatform.GetCurNpuArch());
108	            OP_LOGD(context, "npu arch is %d", arch);
109	            if (arch == (int32_t)NpuArch::DAV_RESV) {
110	                OP_LOGE(op_type, "Do op tiling failed, cannot find npu arch.");
111	                return ge::GRAPH_FAILED;
112	            }
113	        }
114	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, arch);
115	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
116	            auto tilingTemplate = it->second(context);
117	            if (tilingTemplate != nullptr) {
118	                ge::graphStatus status = tilingTemplate->DoTiling();
119	                if (status != ge::GRAPH_PARAM_INVALID) {
120	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
121	                    return status;
122	                }
123	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
124	            }
125	        }
126	        OP_LOGE(op_type, "Do op tiling failed, no valid template is found.");
127	        return ge::GRAPH_FAILED;
128	    }
